import assert from "node:assert/strict";
import { SECURITY_HEADERS } from "../../config/security-headers.mjs";

export function createHtaccess() {
  return [
    "# Generated by build:sakura. Enable HTTPS forwarding in the Sakura control panel.",
    "DirectoryIndex index.html",
    "Options -Indexes -MultiViews",
    "AddType application/wasm .wasm",
    "AddType text/javascript .js .mjs",
    ...Object.entries(SECURITY_HEADERS).flatMap(([name, value]) => [
      `Header onsuccess unset ${name}`,
      `Header always set ${name} "${value}"`,
    ]),
    'Header onsuccess unset Cache-Control',
    'Header always set Cache-Control "no-cache"',
    '<FilesMatch "^\\.">',
    '  Require all denied',
    '</FilesMatch>',
    '',
  ].join("\n");
}

export function deploymentUrl(value) {
  let url;
  try {
    url = new URL(value);
  } catch {
    throw new Error("Deployment URL must be a valid HTTPS directory URL");
  }
  assert(url.protocol === "https:", "Deployment URL must use HTTPS");
  assert(!url.username && !url.password && !url.search && !url.hash,
    "Deployment URL must not contain credentials, query, or fragment");
  assert(url.pathname.endsWith("/"), "Deployment directory URL must end with /");
  return url;
}

export function verifyResponse(response, file, expected, actual) {
  assert.equal(response.status, 200, `${file}: HTTP status`);
  for (const [name, value] of Object.entries(SECURITY_HEADERS)) {
    assert.equal(response.headers.get(name), value, `${file}: ${name}`);
  }
  const types = { html: ["text/html"], js: ["text/javascript", "application/javascript"],
    css: ["text/css"], wasm: ["application/wasm"] };
  const allowed = types[file.split(".").at(-1)];
  if (allowed) {
    assert(allowed.includes(response.headers.get("content-type")?.split(";")[0].trim()),
      `${file}: unexpected Content-Type`);
  }
  assert.equal(response.headers.get("cache-control"), "no-cache", `${file}: Cache-Control`);
  assert(expected.equals(actual), `${file}: deployed content differs from local dist`);
}
